109:    * 입문 허브는 등록 개념이 없어 시각이 없으므로 최근순이 원래 순서로 물러난다 —
110:    * Basic 1·2·3 의 의도된 난이도 순서가 그대로 지켜진다.
111:    */
112:   const [sortKey, setSortKey] = useState<RouteSortKey>("recent");
113:   const [queryText, setQueryText] = useState("");
114:   const query = normalizeForSearch(queryText);
115:   const sortFields = (c: PublishedPublicCourseSummary) => ({
116:     name: publicationDisplayTitle(c),
117:     distanceMeters: c.distanceMeters,
118:     updatedAtMs: c.publishedAtMs ?? null,
119:   });
120:   const introCourses = useMemo(
121:     () => sortRouteList(props.basicSharedHubs.filter((c) => matchesQuery(c, query)), sortKey, sortFields),
122:     [props.basicSharedHubs, sortKey, query],
123:   );
124:   const publicCourses = useMemo(
125:     () => sortRouteList(props.publishedPublicCourses.filter((c) => matchesQuery(c, query)), sortKey, sortFields),
126:     [props.publishedPublicCourses, sortKey, query],
127:   );
128:   /** 두 개 이하면 정렬이 의미 없다 — 좁은 화면에서 줄만 먹는다 */
129:   const sortableCount =
130:     props.segment === "intro" ? props.basicSharedHubs.length : props.publishedPublicCourses.length;
131:   const sortBar =
132:     sortableCount > 2 ? (
133:       <div className="oc-modal__sortbar">
134:         <RouteSortSelect
135:           value={sortKey}
136:           onChange={setSortKey}
137:           keys={["recent", "distance", "name"]}
138:         />
139:       </div>
140:     ) : null;
141: 
142:   const body =
143:     props.segment === "intro" ? (
144:       <>
145:         {props.basicActiveHubCourseId ? (
146:           <p className="oc-modal__hint" role="status">
147:             선택:{" "}
148:             <strong>
149:               {props.basicSharedHubs.find((h) => h.id === props.basicActiveHubCourseId)?.title ??
150:                 props.basicActiveHubCourseId}
151:             </strong>
152:           </p>
153:         ) : null}
154:         {props.basicSharedHubs.length === 0 ? (
155:           <p className="oc-modal__hint">입문 경로 없음</p>
156:         ) : (
157:           <>
158:           {sortBar}
159:           {introCourses.length === 0 ? <p className="oc-modal__hint">검색 결과가 없습니다.</p> : null}
160:           <ul className="oc-modal__list">
161:             {introCourses.map((c) => (
162:               <PublicCoursePickRow
163:                 key={c.id}
164:                 course={c}
165:                 selected={props.basicActiveHubCourseId === c.id}
166:                 loadDisabled={loadDisabled}
167:                 activityBadge={formatRouteActivityListBadge(
168:                   props.publicationActivityByPublicationId?.get(c.id) ?? null,
169:                 )}
170:                 onLoad={() => handleLoad(c.id)}
171:               />
172:             ))}
173:           </ul>
174:           </>
175:         )}
176:         {props.basicStartHubJoined ? (
177:           <button
178:             type="button"
179:             className="oc-modal__leave"
180:             disabled={props.basicStartLoading}
181:             title="Leave course"
182:             onClick={() => {
183:               void props.onLeaveBasicHub();
184:               props.onClose();
185:             }}
186:           >
187:             나가기
188:           </button>
189:         ) : null}
190:       </>
191:     ) : (
192:       <>
193:         {!props.officialCourseCatalogAvailable ? (
194:           <p className="oc-modal__hint">목록 미연결</p>
195:         ) : props.publishedPublicCoursesLoading ? (
196:           <p className="oc-modal__hint">불러오는 중…</p>
197:         ) : props.publishedPublicCoursesError ? (
198:           <p className="oc-modal__error" role="alert">
199:             목록을 불러오지 못했어요.{" "}
200:             <span className="oc-modal__error-detail">{props.publishedPublicCoursesError}</span>
201:           </p>
202:         ) : props.publishedPublicCourses.length === 0 ? (
203:           <p className="oc-modal__hint">
204:             {!props.signedIn && props.officialCourseCatalogAvailable
205:               ? "로그인 후 목록"
206:               : "퍼블릭 경로 없음"}
207:           </p>
208:         ) : (
209:           <>
210:           {sortBar}
211:           {publicCourses.length === 0 ? <p className="oc-modal__hint">검색 결과가 없습니다.</p> : null}
212:           <ul className="oc-modal__list">
213:             {publicCourses.map((c) => (
214:               <PublicCoursePickRow
215:                 key={c.id}
216:                 course={c}
217:                 selected={props.basicActiveHubCourseId === c.id}
218:                 loadDisabled={loadDisabled}
219:                 activityBadge={formatRouteActivityListBadge(
220:                   props.publicationActivityByPublicationId?.get(c.id) ?? null,
221:                 )}
222:                 onLoad={() => handleLoad(c.id)}
223:               />
224:             ))}
225:           </ul>
226:           </>
227:         )}
228:       </>
229:     );
230: 
231:   return (
232:     <RouteListModalShell
233:       titleId="oc-modal-title"
234:       title={segmentChip(props.segment)}
235:       dialogLabel={segmentTitle(props.segment)}
236:       searchValue={queryText}
237:       onSearchChange={setQueryText}
238:       onClose={props.onClose}
239:     >
240:       {body}
241:     </RouteListModalShell>
242:   );
243: }

