.oc-modal[aria-label="퍼블릭 경로"] .oc-modal__error-detail {
  overflow-wrap: anywhere;
}

/* ── 지시27: 입문 경로 목록 한정 (공용 base·퍼블릭 기존 rule 불변, 입문 override만 append) ── */

/* 1. 입문이 든 창만 460px·상한까지. 소수 0/1/2/빈은 내용 높이로 끝나며, 폭/높이 고정 없음. */
.oc-modal-overlay:has(.oc-modal[aria-label="입문 경로"]) {
  padding: 8px;
}

.oc-modal[aria-label="입문 경로"] {
  position: relative;
  width: min(460px, calc(100vw - 16px));
  max-height: calc(100vh - 16px);
  max-height: calc(100dvh - 16px);
}

/* 2. 헤더 한 행 — 퍼블릭 compact값 참고. 폰트·높이·동작 불변, 닫기 자리(우 2.4rem) 유지. */
.oc-modal[aria-label="입문 경로"] .oc-modal__head {
  padding: 0.5rem 2.4rem 0.5rem 0.65rem;
}

.oc-modal[aria-label="입문 경로"] .oc-modal__body {
  padding: 0.5rem 0.6rem 0.6rem;
}

/* 정렬 바가 있을 때만(3개 이상) 헤더 한 행 안에 absolute. 없으면 검색이 전체 가용폭. */
.oc-modal[aria-label="입문 경로"] .oc-modal__sortbar {
  position: absolute;
  top: 0;
  right: 2.4rem;
  height: 3rem;
  margin: 0;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  white-space: nowrap;
}

.oc-modal[aria-label="입문 경로"]:has(.oc-modal__sortbar) .oc-modal__search {
  margin-right: 6.5rem;
}

/* 3. 카드 반복을 행 구분선·gap 0으로 정리. 이번 입문 선택행은 min 44px 유지
   (32px 예외는 Chief 지정 내 경로/퍼블릭만). 전체 텍스트·수단거리·활동 배지 보존. */
.oc-modal[aria-label="입문 경로"] .oc-modal__list {
  gap: 0;
  border-top: 1px solid #E2E8F0;
}

.oc-modal[aria-label="입문 경로"] .oc-modal__item {
  border: none;
  border-bottom: 1px solid #E2E8F0;
  border-radius: 0;
  background: transparent;
  box-sizing: border-box;
  min-height: 44px;
  height: auto;
  padding: 2px 0.55rem;
}

.oc-modal[aria-label="입문 경로"] .oc-modal__item:hover:not(:disabled) {
  background: #EFF6FF;
}

.oc-modal[aria-label="입문 경로"] .oc-modal__item.is-selected {
  background: #EFF6FF;
  box-shadow: inset 3px 0 0 0 #2563EB;
}

.oc-modal[aria-label="입문 경로"] .oc-modal__item-name {
  line-height: 1.2;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.oc-modal[aria-label="입문 경로"] .oc-modal__item-sub {
  flex-wrap: wrap;
  row-gap: 0.1rem;
  margin-top: 1px;
  line-height: 1.2;
}

.oc-modal[aria-label="입문 경로"] .oc-modal__item-publisher {
  flex-shrink: 1;
  min-width: 0;
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
  text-align: right;
}

/* 4. 선택 안내·나가기는 그대로. 긴 선택 안내/오류(예외 有) 내용 접근,
   일반은 목록만 스크롤·헤더(본문 밖) 고정. */
.oc-modal[aria-label="입문 경로"] .oc-modal__hint {
  overflow-wrap: anywhere;
}

.oc-modal[aria-label="입문 경로"] .oc-modal__body:has(.oc-modal__error) {
  overflow-x: hidden;
  overflow-y: auto;
}

.oc-modal[aria-label="입문 경로"] .oc-modal__error {
  flex-shrink: 0;
}

.oc-modal[aria-label="입문 경로"] .oc-modal__error-detail {
  overflow-wrap: anywhere;
}

